import{_ as o,l as i,o as e,c as n,v as t,p as s,x as r,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"过长过滤","description":"","frontmatter":{"title":"过长过滤","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/overlong-filtering.md","filePath":"llm/overlong-filtering.md","lastUpdated":1789023840000}'),p={name:"llm/overlong-filtering.md"};function c(A,a,_,E,f,u){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="过长过滤" tabindex="-1">过长过滤 <a class="header-anchor" href="#过长过滤" aria-label="Permalink to &quot;过长过滤&quot;">​</a></h1><div class="epigraph"><p>截断不是答错；把超长样本直接标成负奖励，会误伤写对但还没写完的推理。</p><footer>—— Yu 等 DAPO 的 overlong filtering 与软超长塑形</footer></div><p><a href="/llm/entropy-collapse">上一课</a>处理探索死亡。探索活着时，另一头出现：模型把链写到生成上限，被截断。缺口是：<strong>截断轨迹的 \\(R\\) 怎么计，会决定策略怕长度还是利用长度。</strong> DAPO 把「超长过滤 + 软惩罚」写成从 30 分走到更高分的第一块增量。本课写过滤，不重写 <a href="/llm/verifiable-reward">可验证奖励</a> 的抽取。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>生成设 <code>max_tokens = L</code>。到 \\(L\\) 仍无 EOS，轨迹不完整：数学可能还没 boxed，代码可能还没写完测试。若抽取失败则 \\(R=0\\)，等于把「推理方向对、预算不够」标成错。梯度会惩罚这类前缀，策略学会要么极短，要么在预算内胡乱收尾。若忽略截断样本（mask 损失），则浪费生成，但至少不注入错误标签。</p><p>DAPO：先可对截断样本 mask；再给软惩罚——长度 \\(\\le L_{\\max}-L_{\\mathrm{cache}}\\) 不罚，中间线性到 \\(-1\\)，\\(|y|\\gt L_{\\max}\\) 为 \\(-1\\)。主实验 \\(L_{\\max}=16384\\)、\\(L_{\\mathrm{cache}}=4096\\)，生成上限更大。过滤与塑形一起，消融上「+超长过滤」从 30 到 36。</p><h3 id="过滤的是损失-不是数据删除" tabindex="-1">过滤的是损失，不是数据删除 <a class="header-anchor" href="#过滤的是损失-不是数据删除" aria-label="Permalink to &quot;过滤的是损失，不是数据删除&quot;">​</a></h3><p>仍要记账截断率。截断率高，说明 \\(L\\) 不够或模型在拖。只 mask 而不改 \\(L\\)，墙钟被长尾吃掉。\\(L\\) 与塑形阈值必须一起调；预算 4K 却抄 16K 阈值，等于关掉机制。</p><p><span class="marginnote">长度惩罚与 RM 爱长对冲。可验证域没有 RM 爱长，过长主要来自重复与过度搜索，见后课过度思考。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：标记 <code>truncated</code>。训练目标对截断 token 的策略损失 mask，或整条 mask。奖励侧：不把截断当答错；另加连续软惩罚 \\(p(|y|)\\in[-1,0]\\)，与校验器 \\(R_{\\mathrm{acc}}\\) 相加。评测必须用与训练一致的 \\(L\\)，否则准确率不可比。不要在抽取器里对截断序列「强行抓最后一个数字」——假阳性会奖励没写完的链。</p>',11)),(e(),s(h,null,{default:r(()=>[d(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%94%9F%E6%88%90%E8%87%B3%E4%B8%8A%E9%99%90%22%5D%20--%3E%20TR%5B%22%E6%A0%87%E8%AE%B0%E6%88%AA%E6%96%AD%22%5D%0A%20%20TR%20--%3E%20MASK%5B%22%E6%8D%9F%E5%A4%B1%20mask%22%5D%0A%20%20TR%20--%3E%20SOFT%5B%22%E8%BD%AF%E9%95%BF%E5%BA%A6%E6%83%A9%E7%BD%9A%22%5D%0A%20%20ACC%5B%22%E6%A0%A1%E9%AA%8C%E5%99%A8%E5%AF%B9%E9%94%99%22%5D%20--%3E%20SUM%5B%22R%20%3D%20%E5%AF%B9%E9%94%99%20%2B%20p(%7Cy%7C)%22%5D%0A%20%20SOFT%20--%3E%20SUM%0A%20%20SUM%20--%3E%20ADV%5B%22%E4%BC%98%E5%8A%BF%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 <a href="/llm/length-normalization-bias">长度归一化</a> 的差别：这里不除 \\(|y|\\)，只在尾部加代价。中等长度的正确证明不受伤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>mask 切断错误信用：未完成不等于 \\(R=0\\)。软惩罚提供可微的「请在预算内结束」而不污染对错几何。策略学会在 \\(L_{\\mathrm{cache}}\\) 窗口里收束 boxed。若惩罚过早，又打压必要长链——与 R1 鼓励长思考的目标冲突，阈值要按任务分位数设，而不是抄论文整数。</p><p><span class="marginnote">截断率突然上升常与熵塌后的重复循环同现。先看 n-gram 重复，再加大 \\(L\\)。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>服务侧 SLA 更短时，训练 \\(L\\) 必须覆盖产品预算，否则过长过滤教的是另一套停止策略。工具调用中途截断同理，应 mask。下一课动态采样处理零梯度组；过长组若仍算出 \\(R\\)，会进 batch，不要与 0/1 准确率过滤混为一谈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>截断 ≠ 答错；直接赋 0 会误伤未写完的正确推理。</li><li>DAPO：mask 截断损失 + 尾部软惩罚，阈值与生成预算绑定。</li><li>不要对截断序列强行抽取答案。</li><li>截断率是一等监控，常与重复循环同现。</li><li>出处：Yu 等 DAPO overlong filtering / shaping。</li></ul>',8))])}const k=o(p,[["render",c]]);export{B as __pageData,k as default};
